import React, { useState, useEffect } from "react";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver";
import "./AdminDashboard.css";

export default function AdminDashboard() {
  const [selectedBranch, setSelectedBranch] = useState(null);
  const [branchAttendance, setBranchAttendance] = useState([]);
  const [loading, setLoading] = useState(false);
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  const branches = ["Hitech City", "Vanasthalipuram", "Nagole"];

  // === UPDATE THIS LIST WITH YOUR COMPANY'S PUBLIC HOLIDAYS (YYYY-MM-DD) ===
  const PUBLIC_HOLIDAYS_2026 = [
    "2026-01-01", // New Year's Day
    "2026-01-26", // Republic Day
    "2026-03-30", // Holi (example)
    "2026-08-15", // Independence Day
    "2026-10-02", // Gandhi Jayanti
    "2026-12-25", // Christmas
    // Add more as per your region/company policy
  ];

  useEffect(() => {
    if (localStorage.getItem("role") !== "admin") {
      window.location.href = "/";
    }
  }, []);

  const fetchBranchAttendance = async (branch) => {
    setLoading(true);
    setSelectedBranch(branch);
    try {
      const res = await fetch(`http://localhost:5000/api/attendance/branch/${encodeURIComponent(branch)}`);
      if (!res.ok) throw new Error("Failed to fetch attendance");
      const data = await res.json();
      setBranchAttendance(data);
    } catch (err) {
      alert("Failed to load branch attendance");
      console.error(err);
      setBranchAttendance([]);
    } finally {
      setLoading(false);
    }
  };

  const viewFullAttendance = (employee) => {
    const params = new URLSearchParams({
      userId: employee.userId,
      name: employee.name,
      designation: employee.designation || "N/A",
      branch: selectedBranch,
    });
    window.location.href = `/attendance-details?${params.toString()}`;
  };

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/";
  };

  const generateDateRange = (start, end) => {
    const dates = [];
    const current = new Date(start);
    while (current <= end) {
      dates.push(new Date(current).toISOString().split("T")[0]);
      current.setDate(current.getDate() + 1);
    }
    return dates;
  };

  const countWorkingDays = (start, end) => {
    let count = 0;
    const current = new Date(start);
    while (current <= end) {
      const day = current.getDay();
      const dateStr = current.toISOString().split("T")[0];
      if (day !== 0 && !PUBLIC_HOLIDAYS_2026.includes(dateStr)) count++; // Exclude Sunday & Holidays
      current.setDate(current.getDate() + 1);
    }
    return count;
  };

  const handleExport = async () => {
    if (!selectedBranch) {
      alert("Please select a branch first");
      return;
    }
    if (!fromDate || !toDate) {
      alert("Please select both From and To dates");
      return;
    }

    const startDate = new Date(fromDate);
    const endDate = new Date(toDate);
    if (startDate > endDate) {
      alert("From date cannot be after To date");
      return;
    }

    const allDates = generateDateRange(startDate, endDate);
    const totalWorkingDays = countWorkingDays(startDate, endDate);

    setLoading(true);
    try {
      const exportRows = [];
      const sheetStyles = []; // To store cell styles (color)

      await Promise.all(
        branchAttendance.map(async (emp, rowIndex) => {
          let fullRecords = [];
          try {
            const res = await fetch(`http://localhost:5000/api/attendance/${emp.userId}`);
            if (res.ok) fullRecords = await res.json();
          } catch (e) {
            console.warn(`No data for ${emp.userId}`);
          }

          const recordMap = new Map(fullRecords.map((r) => [r.date, r]));

          const row = {
            Name: emp.name,
            ID: emp.userId,
          };

          let presentCount = 0;
          let halfDayCount = 0;

          allDates.forEach((dateStr) => {
            const dateObj = new Date(dateStr);
            const dayOfWeek = dateObj.getDay(); // 0 = Sunday, 6 = Saturday
            const isHoliday = PUBLIC_HOLIDAYS_2026.includes(dateStr);

            if (isHoliday) {
              row[dateStr] = "HOL";
              // Store style: red background
              sheetStyles.push({ cell: XLSX.utils.encode_cell({ c: 2 + allDates.indexOf(dateStr), r: rowIndex + 1 }), style: { fill: { fgColor: { rgb: "FFFF0000" } } } });
            } else if (dayOfWeek === 6) {
              row[dateStr] = "SAT";
              // Store style: gray background
              sheetStyles.push({ cell: XLSX.utils.encode_cell({ c: 2 + allDates.indexOf(dateStr), r: rowIndex + 1 }), style: { fill: { fgColor: { rgb: "FFD3D3D3" } } } });
            } else {
              const rec = recordMap.get(dateStr);
              if (!rec || !rec.checkIn || !rec.checkOut) {
                row[dateStr] = "A";
              } else {
                const [inH, inM, inS] = rec.checkIn.split(":").map(Number);
                const [outH, outM, outS] = rec.checkOut.split(":").map(Number);

                const checkInDecimal = inH + inM / 60 + inS / 3600;
                const checkOutDecimal = outH + outM / 60 + outS / 3600;

                const lateHours = Math.max(0, checkInDecimal - 9.25);
                const earlyHours = Math.max(0, 18.5 - checkOutDecimal);

                if (lateHours > 2 || earlyHours > 2) {
                  row[dateStr] = "H";
                  halfDayCount++;
                } else {
                  row[dateStr] = "P";
                  presentCount++;
                }
              }
            }
          });

          row["Total Working Days"] = totalWorkingDays;
          row["Present Days"] = presentCount;
          row["Half Days"] = halfDayCount;

          exportRows.push(row);
        })
      );

      // Create worksheet
      const worksheet = XLSX.utils.json_to_sheet(exportRows, { skipHeader: false });

      // Column widths
      const baseCols = [{ wch: 22 }, { wch: 12 }];
      const dateCols = allDates.map(() => ({ wch: 9 }));
      const summaryCols = [{ wch: 18 }, { wch: 14 }, { wch: 12 }];
      worksheet["!cols"] = [...baseCols, ...dateCols, ...summaryCols];

      // Apply cell colors
      if (!worksheet["!ref"]) return;
      worksheet["!ref"] = worksheet["!ref"]; // Ensure ref exists

      sheetStyles.forEach(({ cell, style }) => {
        if (!worksheet[cell]) worksheet[cell] = {};
        if (!worksheet[cell].s) worksheet[cell].s = {};
        worksheet[cell].s.fill = style.fill;
      });

      // Bold header row
      const range = XLSX.utils.decode_range(worksheet["!ref"]);
      for (let C = range.s.c; C <= range.e.c; ++C) {
        const cell = worksheet[XLSX.utils.encode_cell({ c: C, r: 0 })];
        if (cell) {
          cell.s = { font: { bold: true }, alignment: { horizontal: "center" } };
        }
      }

      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Attendance");

      const buffer = XLSX.write(workbook, { bookType: "xlsx", type: "array" });
      const blob = new Blob([buffer], { type: "application/octet-stream" });
      const fileName = `${selectedBranch}_Attendance_${fromDate}_to_${toDate}.xlsx`;

      saveAs(blob, fileName);
    } catch (err) {
      console.error("Export failed:", err);
      alert("Failed to generate export. Check console.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="admin-dashboard">
      <div className="admin-header">
        <h1>Admin Dashboard - Attendance Overview</h1>
        <button className="logout-btn" onClick={handleLogout}>Logout</button>
      </div>

      <div className="branches-grid">
        {branches.map((branch) => (
          <div
            key={branch}
            className={`branch-card ${selectedBranch === branch ? "active" : ""}`}
            onClick={() => fetchBranchAttendance(branch)}
          >
            <h3>{branch}</h3>
            <p>Click to view today's attendance</p>
          </div>
        ))}
      </div>

      {selectedBranch && (
        <div className="attendance-section">
          <h2>Today's Attendance - {selectedBranch}</h2>
          <p><strong>Date:</strong> {new Date().toLocaleDateString()}</p>

          <div className="export-section">
            <div className="date-inputs">
              <label>From:</label>
              <input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} />
              <label>To:</label>
              <input type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} />
            </div>
            <button
              onClick={handleExport}
              disabled={loading || !fromDate || !toDate}
              className="export-btn"
            >
              {loading ? "Exporting..." : "Export Attendance Report"}
            </button>
          </div>

          {loading && !branchAttendance.length ? (
            <p>Loading attendance data...</p>
          ) : branchAttendance.length === 0 ? (
            <p>No employees or attendance data for this branch today.</p>
          ) : (
            <table className="branch-attendance-table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>ID</th>
                  <th>Designation</th>
                  <th>Status</th>
                  <th>Check In</th>
                  <th>Check Out</th>
                  <th>Hours</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {branchAttendance.map((emp) => (
                  <tr key={emp.userId} className={emp.status === "Absent" ? "absent-row" : ""}>
                    <td>{emp.name}</td>
                    <td>{emp.userId}</td>
                    <td>{emp.designation}</td>
                    <td>
                      <span className={`status-badge status-${emp.status.toLowerCase().replace(" ", "-")}`}>
                        {emp.status}
                      </span>
                    </td>
                    <td>{emp.checkIn}</td>
                    <td>{emp.checkOut}</td>
                    <td>{emp.hours}</td>
                    <td>
                      <button className="view-full-btn" onClick={() => viewFullAttendance(emp)}>
                        Full History
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}
